import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "../env";

/**
 * File storage for PDFs. Local disk (a Docker volume in production); the
 * interface is small so it can move to object storage later.
 * Keys are generated by us (`<workspaceId>/<paperId>.pdf`), never user input.
 */
function resolveKey(key: string): string {
  if (!/^[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+\.pdf$/.test(key)) throw new Error("Invalid storage key");
  return path.join(path.resolve(env().UPLOAD_DIR), key);
}

export function paperFileKey(workspaceId: string, paperId: string) {
  return `${workspaceId}/${paperId}.pdf`;
}

export async function saveFile(key: string, data: Buffer) {
  const file = resolveKey(key);
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, data);
}

export async function loadFile(key: string): Promise<Buffer> {
  return readFile(resolveKey(key));
}

export async function deleteFile(key: string) {
  await rm(resolveKey(key), { force: true });
}

/** PDF files start with "%PDF-" (allowing a little leading junk, as readers do). */
export function looksLikePdf(data: Buffer): boolean {
  return data.subarray(0, 1024).includes(Buffer.from("%PDF-"));
}
